import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.BW2T23B9.js";const _=JSON.parse('{"title":"教师指南","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/teacher-guide.md","filePath":"authoring/teacher-guide.md","lastUpdated":null}'),r={name:"authoring/teacher-guide.md"};function l(n,e,d,c,s,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="教师指南" tabindex="-1">教师指南 <a class="header-anchor" href="#教师指南" aria-label="Permalink to &quot;教师指南&quot;">​</a></h1><p>面向不写代码的老师：用桌面编辑器打开课程文件夹，新增或改一节「认识新词」（intro）课，保存前用教师模式把题目点一遍。</p><p>编辑器能力总览见 <a href="/docs/guide/editor">课程编辑器</a>。完整逐步说明（含验收标准）在应用仓库 <code>docs/authoring/teacher-guide.md</code>。</p><h2 id="准备一次即可" tabindex="-1">准备一次即可 <a class="header-anchor" href="#准备一次即可" aria-label="Permalink to &quot;准备一次即可&quot;">​</a></h2><ol><li>拿到 <code>turna-gui.exe</code>（或对应平台的可执行文件），双击运行，不需要安装 Python。</li><li>向技术人员要一份课程目录副本，例如桌面上的 <code>我的课程/turkish/</code>。不要直接改团队共享目录，改完再合并。</li></ol><h2 id="产出一节-intro-课" tabindex="-1">产出一节 intro 课 <a class="header-anchor" href="#产出一节-intro-课" aria-label="Permalink to &quot;产出一节 intro 课&quot;">​</a></h2><ol><li>打开课程目录。左侧出现 Section → Unit → Lesson。</li><li>在目标 Unit 上右键 →「新增 Lesson」。程序会生成 id，老师只填名称。</li><li>填写名称、一句话描述，以及同 Unit 内必须先完成的课。</li><li>课型选 <strong>intro（认识新词）</strong>。模板会生成默认结构：展示新词 → 选择释义 → 填空巩固。</li><li>把词汇和题目填进各阶段。词汇应来自课程的 <code>vocab.json</code>，不要在课时里发明另一套词表。</li><li>保存。校验失败会回滚，不会留下半截 JSON。</li><li>打开教师模式，按学员顺序做一遍，确认音频、正确答案和先修关系。</li></ol><h2 id="常见约束" tabindex="-1">常见约束 <a class="header-anchor" href="#常见约束" aria-label="Permalink to &quot;常见约束&quot;">​</a></h2><ul><li>每个 Section 的 Unit 数、每个 Unit 的课时数有上限（见 <a href="/docs/authoring/course-layout">课程目录约定</a>）。</li><li>先修只在同 Unit 内勾选，跨 Unit / Section 的解锁由课程树更高层处理。</li><li>听力课需要音频资源；没有音频时先做 intro / practice，再补听力。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/guide/lesson-types">课型说明</a></li></ul>',11)])])}const p=a(r,[["render",l]]);export{_ as __pageData,p as default};
